from thresholdsign import (
    Rotation, RotationChain, RHE, make_history_extension, check_rhe,
    encode_rhe, decode_rhe,
)
from test_rotation_chain import make_key, make_cert
from test_seal_history import make_history, sign_message as hist_sign
import dataclasses

k0 = make_key((1,2,3), 2, seed_offset=0)
k1 = make_key((2,3,4,5), 3, seed_offset=10)
k2 = make_key((3,4,5,6), 2, seed_offset=20)
history = make_history(k0, nonces=tuple(600+i for i in range(6)))
old_msg, new_msg, ext = make_history_extension(history, 3)
c0 = make_cert(k0, k1, (1,3), t=3, seed=100)
c1 = make_cert(k1, k2, (2,4,5), t=2, seed=200)
chain = RotationChain(k0.public_key, (c0, c1))
old_sig = hist_sign(old_msg, k0, seed=700)
new_sig = hist_sign(new_msg, k2, signer_ids=(4,5), seed=710)
x = RHE(ext, chain, old_sig, new_sig)
chain1 = RotationChain(k0.public_key, (c0,))
new_sig1 = hist_sign(new_msg, k1, signer_ids=(2,4,5), seed=720)
x1 = RHE(ext, chain1, old_sig, new_sig1)
print('check_rhe 1-hop:', check_rhe(x1))
print('swapped -> False:', check_rhe(dataclasses.replace(x, old_sig=new_sig)) is False)
chain_bad = RotationChain(k1.public_key, (c0, c1))
print('wrong anchor -> False:', check_rhe(RHE(ext, chain_bad, old_sig, new_sig)) is False)
print('old sig under k1 -> False:', check_rhe(RHE(ext, chain, hist_sign(old_msg, k1, signer_ids=(2,4,5), seed=730), new_sig)) is False)
# leaf tamper
leaves_bad = ext.leaves[:1] + (bytes(ext.leaves[1][:1] + bytes([ext.leaves[1][1]^1])),) + ext.leaves[2:] if False else ext.leaves
flipped = bytearray(ext.leaves[1]); flipped[0] ^= 1
bad_ext = dataclasses.replace(ext, leaves=ext.leaves[:1]+(bytes(flipped),)+ext.leaves[2:])
print('tampered leaf -> False:', check_rhe(RHE(bad_ext, chain, old_sig, new_sig)) is False)
# type/value errors
for bad in ('x', 42, None):
    try: check_rhe(bad)
    except TypeError: pass
    else: print('FAIL TypeError', bad)
try:
    check_rhe(RHE(ext, RotationChain(k0.public_key, ()), old_sig, new_sig))
except ValueError: print('empty chain -> ValueError OK')
try:
    encode_rhe('x')
except TypeError: print('encode TypeError OK')
for bad in (bytearray(encode_rhe(x)), 'b', 42, None):
    try: decode_rhe(bad)
    except TypeError: pass
    else: print('FAIL decode TypeError', type(bad))
blob = encode_rhe(x)
for cut in (0, 8, 9, len(blob)-1):
    try: decode_rhe(blob[:cut])
    except ValueError: pass
    else: print('FAIL trunc at', cut)
try: decode_rhe(blob + b'x')
except ValueError: print('trailing -> ValueError OK')
