import thresholdsign as ts
# build chain frame with count 0: tag rotation-chain + u32(0)
rc_tag = b"thresholdsign/rotation-chain/v1"
eframe_body = ext.old_total.to_bytes(8,'big') + len(ext.leaves).to_bytes(8,'big') + b''.join(ext.leaves)
bad_wire = b"ts/rhe/v1" + len(eframe_body).to_bytes(4,'big') + eframe_body + len(rc_tag + (0).to_bytes(4,'big')).to_bytes(4,'big') + rc_tag + (0).to_bytes(4,'big')
try: decode_rhe(bad_wire)
